import dataset from "@/data/goatMarket.json"
import type { GoatMarketData } from "@/types"

// Generated by `npm run data:goat` from official sources. See data/goat-market/README.md.
export const GOAT_MARKET = dataset as GoatMarketData

export const DEFAULT_STATE = "Odisha"

export const MARKET_SOURCE = GOAT_MARKET.sources["lc20-pib-annexure"]

export const DATA_TYPE_LABEL: Record<string, string> = {
  official_census: "Official census count",
  official_statistics: "Official statistics",
  survey_estimate: "Survey estimate",
  calculated: "Calculated estimate",
}

// Rank, share and map shading are plain arithmetic on the census counts, nothing is estimated.
const counted = Object.entries(GOAT_MARKET.states)
  .filter(([, state]) => typeof state.goatPopulation === "number")
  .map(([name, state]) => [name, state.goatPopulation as number] as const)
  .sort((a, b) => b[1] - a[1])

export const NATIONAL_GOATS = counted.reduce((sum, [, goats]) => sum + goats, 0)
export const RANKED_STATES = counted.map(([name]) => name)
export const TOP_STATES = RANKED_STATES.slice(0, 5)

// Five equal-sized groups by rank: 5 = the most goats, 1 = the fewest
const GROUP_SIZE = Math.ceil(counted.length / 5)
export const MAP_LEVELS: Record<string, number> = Object.fromEntries(
  RANKED_STATES.map((name, i) => [name, 5 - Math.floor(i / GROUP_SIZE)]),
)
